def pasar_a_escala_de_10(apps, schema_editor):
    """Las calificaciones de 1 a 5 estrellas pasan a la escala de 1 a 10 (×2) y toman la fecha en que se dieron."""
    Ticket = apps.get_model("tickets", "Ticket")
    Seguimiento = apps.get_model("tickets", "Seguimiento")
    for t in Ticket.objects.filter(calificacion__isnull=False):
        seg = Seguimiento.objects.filter(ticket=t, tipo="calificacion").order_by("-creado").first()
        t.calificacion = min(t.calificacion * 2, 10)
        t.fecha_calificacion = seg.creado if seg else (t.fecha_cierre or t.actualizado)
        t.save(update_fields=["calificacion", "fecha_calificacion"])


def volver_a_escala_de_5(apps, schema_editor):
    Ticket = apps.get_model("tickets", "Ticket")
    for t in Ticket.objects.filter(calificacion__isnull=False):
        t.calificacion = max(1, round(t.calificacion / 2))
        t.save(update_fields=["calificacion"])


